const express = require('express');
const crypto = require('crypto');
const { EmployeeDirectory, EnterpriseDomainRegistry } = require('../models/directory');

const app = express();
app.use(express.json());

app.post('/api/webhooks/auth0/sync-user', async (req, res) => {
  // Verify webhook HMAC signature
  const signature = req.headers['x-auth0-hmac'];
  const calculatedSig = crypto
    .createHmac('sha256', process.env.AUTH0_SYNC_SECRET)
    .update(JSON.stringify(req.body))
    .digest('hex');

  if (!signature || signature !== calculatedSig) {
    return res.status(401).json({ error: 'Invalid webhook signature' });
  }

  const { externalUserId, targetCompanyDomain, corporateMetadata } = req.body;

  const employee = await EmployeeDirectory.findOne({
    where: { externalId: externalUserId }
  });

  if (!employee) {
    return res.status(404).json({ error: 'Employee directory entry not found' });
  }

  // Confirm targetCompanyDomain matches the employee's registered corporate domain
  const domainValid = await EnterpriseDomainRegistry.verifyDomain(employee.companyId, targetCompanyDomain);
  if (!domainValid) {
    return res.status(403).json({ error: 'Access denied: domain does not match employee corporate registration' });
  }

  employee.securityClearance = corporateMetadata.securityClearance;
  employee.assignedDepartment = corporateMetadata.department;
  await employee.save();

  res.json({ updated: true, employeeId: employee.id });
});

app.listen(9003);
